"""A dedicated flat-terrain population with fixed high foot friction."""

import numpy as np
import torch

from isaaclab.envs.mdp.events import randomize_rigid_body_material
from isaaclab.managers import SceneEntityCfg


class HighFrictionFlatMaterial(randomize_rigid_body_material):
    """Override foot materials only for columns generated by the named flat terrain.

    Uses the same column selection rule as TerrainGenerator's curriculum. Terrain
    types stay fixed across episode resets and difficulty curriculum updates.
    """

    def __call__(self, env, env_ids, asset_cfg: SceneEntityCfg, terrain_name: str, friction: float):
        terrain = env.scene.terrain
        mask = torch.zeros(env.num_envs, device=env.device, dtype=torch.bool)
        env.tqbot2_high_friction_flat_mask = mask
        if terrain.cfg.terrain_type == "plane":
            return  # Plane-only diagnostics do not contain the dedicated population.
        generator = terrain.cfg.terrain_generator
        if not generator.curriculum:
            raise ValueError("High-friction flat population requires curriculum terrain columns")
        names = list(generator.sub_terrains)
        index = names.index(terrain_name)
        proportions = np.array([t.proportion for t in generator.sub_terrains.values()])
        cumulative = np.cumsum(proportions / proportions.sum())
        columns = [col for col in range(generator.num_cols)
                   if np.min(np.where(col / generator.num_cols + .001 < cumulative)[0]) == index]
        for col in columns:
            mask |= terrain.terrain_types == col
        selected = torch.where(mask)[0].cpu()
        if env_ids is not None:
            selected = selected[torch.isin(selected, env_ids.cpu())]
        if not len(selected):
            return
        materials = self.asset.root_physx_view.get_material_properties()
        for body_id in self.asset_cfg.body_ids:
            start = sum(self.num_shapes_per_body[:body_id])
            end = start + self.num_shapes_per_body[body_id]
            materials[selected, start:end, :2] = friction
        self.asset.root_physx_view.set_material_properties(materials, selected)
        # Keep this population inside the union of its flat columns, across all rows.
        origins = terrain.terrain_origins[:, columns]
        env.tqbot2_high_friction_flat_bounds = torch.stack((
            origins[..., 0].min() - generator.size[0] / 2,
            origins[..., 0].max() + generator.size[0] / 2,
            origins[..., 1].min() - generator.size[1] / 2,
            origins[..., 1].max() + generator.size[1] / 2,
        ))
        print(f"[TQBot2] high-friction flat: {len(selected)}/{env.num_envs} environments, "
              f"columns={columns}, static=dynamic={friction}", flush=True)


def high_friction_flat_exit(env, margin: float = 0.3):
    """End the special scenario before its robot crosses into a rough terrain patch."""
    mask = getattr(env, "tqbot2_high_friction_flat_mask", None)
    bounds = getattr(env, "tqbot2_high_friction_flat_bounds", None)
    if mask is None or bounds is None:
        return torch.zeros(env.num_envs, device=env.device, dtype=torch.bool)
    position = env.scene["robot"].data.root_link_pos_w
    outside = ((position[:, 0] < bounds[0] + margin) | (position[:, 0] > bounds[1] - margin)
               | (position[:, 1] < bounds[2] + margin) | (position[:, 1] > bounds[3] - margin))
    return mask & outside
